import fs from 'node:fs';
const base64 = fs.readFileSync('logo.png').toString('base64');
const js =
  '// Autogenerated data URI for logo.png so html2pdf never performs a\n' +
  '// cross-origin (file://) fetch that would taint the canvas and break\n' +
  '// toDataURL() (the "PDF download failed. Please try again." error).\n' +
  'const LOGO_DATA_URI = "data:image/png;base64,' + base64 + '";\n';
fs.writeFileSync('logo-data.js', js);
console.log('wrote', fs.statSync('logo-data.js').size, 'bytes');